CREATE TABLE cmd_postal_contract_acceptance_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),postal_contract_id bigint NOT NULL UNIQUE,journey_id bigint NOT NULL,ship_id bigint NOT NULL,actual_mail_tons smallint NOT NULL CHECK(actual_mail_tons BETWEEN 0 AND 5),reserved_mail_tons smallint NOT NULL CHECK(reserved_mail_tons=5),promised_payment_credits integer NOT NULL CHECK(promised_payment_credits=25000),FOREIGN KEY(postal_contract_id,campaign_id) REFERENCES journey_postal_contract(postal_contract_id,campaign_id),FOREIGN KEY(journey_id,campaign_id) REFERENCES journey_journey(journey_id,campaign_id),FOREIGN KEY(ship_id,campaign_id) REFERENCES ship_ship(ship_id,campaign_id));
CREATE TABLE cmd_postal_contract_delivery_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),postal_contract_id bigint NOT NULL UNIQUE,actor_id bigint NOT NULL,financial_transaction_id bigint NOT NULL UNIQUE,balance_after_minor bigint NOT NULL,FOREIGN KEY(postal_contract_id,campaign_id) REFERENCES journey_postal_contract(postal_contract_id,campaign_id),FOREIGN KEY(actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(financial_transaction_id,campaign_id) REFERENCES fin_transaction(transaction_id,campaign_id));
